import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.userData.handlers = {};

  const cleanupTasks = [];

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitiveFn = ctx.primitives[prim.name];
      if (primitiveFn) {
        const result = primitiveFn(group, prim.params);
        if (result?.cleanup) cleanupTasks.push(result.cleanup);
        if (result?.timeline) cleanupTasks.push(() => result.timeline.kill());
      }
    }
  }

  // --- Backdrop plane -------------------------------------------------
  const planeWidth = 1.6; // aspect from image 512x320
  const planeHeight = 1.0;
  const planeGeo = new ctx.THREE.PlaneGeometry(planeWidth, planeHeight);
  const planeMat = new MeshBasicNodeMaterial();
  planeMat.transparent = true;
  const planeMesh = new ctx.THREE.Mesh(planeGeo, planeMat);
  group.add(planeMesh);

  // Load texture synchronously (async side‑effect)
  let loadedTex;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Text content ----------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const colors = config.intent?.visualSpec?.colors || {};

  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 0.34, // headline scale
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    // Slightly lift text above plane to avoid z‑fighting
    txtObj.position.set(0, 0, 0.01);
    group.add(txtObj);
  }

  // --- Cleanup ---------------------------------------------------------
  group.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeo.dispose();
    planeMat.dispose();
    if (loadedTex) loadedTex.dispose();

    // Dispose any text objects created by fontAtlas
    for (const child of group.children) {
      if (child.userData?.isText && child.geometry) {
        child.geometry.dispose();
      }
    }

    // Run primitive cleanups
    for (const fn of cleanupTasks) {
      try {
        fn();
      } catch (_) {}
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return group;
}
